package fs

import (
	"context"
	"io"
	"sync"
	"testing"
	"time"

	"go.flipt.io/flipt/internal/containers"
	"go.uber.org/zap"
)

// UpdateFunc is called periodically by a Poller to check for updates.
type UpdateFunc func(context.Context) (bool, error)

type Poller struct {
	logger  *zap.Logger
	ctx     context.Context
	cancel  context.CancelFunc
	update  UpdateFunc
	done    chan struct{}
	mu      sync.Mutex
	started bool
	closed  bool

	interval time.Duration
	notify   func(modified bool)
}

var _ io.Closer = (*Poller)(nil)

func WithInterval(interval time.Duration) containers.Option[Poller] {
	return func(p *Poller) {
		p.interval = interval
	}
}

func WithNotify(t *testing.T, n func(modified bool)) containers.Option[Poller] {
	t.Helper()
	return func(p *Poller) {
		p.notify = n
	}
}

func NewPoller(ctx context.Context, logger *zap.Logger, update UpdateFunc, opts ...containers.Option[Poller]) *Poller {
	ctx, cancel := context.WithCancel(ctx)
	p := &Poller{
		logger:   logger,
		ctx:      ctx,
		cancel:   cancel,
		update:   update,
		done:     make(chan struct{}),
		interval: 30 * time.Second,
	}
	containers.ApplyAll(p, opts...)
	return p
}

// Poll runs the polling loop. Call it in a goroutine to poll in the background.
func (p *Poller) Poll() {
	p.mu.Lock()
	if p.closed || p.started {
		p.mu.Unlock()
		return
	}
	p.started = true
	p.mu.Unlock()

	defer close(p.done)

	ticker := time.NewTicker(p.interval)
	defer ticker.Stop()
	for {
		select {
		case <-p.ctx.Done():
			return
		case <-ticker.C:
			modified, err := p.update(p.ctx)
			if err != nil {
				p.logger.Error("error getting file system from directory", zap.Error(err))
				continue
			}

			if p.notify != nil {
				p.notify(modified)
			}

			if !modified {
				p.logger.Debug("skipping snapshot update as it has not been modified")
				continue
			}

			p.logger.Debug("snapshot updated")
		}
	}
}

// Close stops polling and waits for its goroutine to terminate.
func (p *Poller) Close() error {
	p.mu.Lock()
	if !p.closed {
		p.closed = true
		p.cancel()
		if !p.started {
			close(p.done)
		}
	}
	done := p.done
	p.mu.Unlock()
	<-done
	return nil
}
